import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Scanner;
import java.util.stream.Collectors;

class Solution {
    public static List<Integer> intersectionOfArrays(List<Integer> nums1, List<Integer> nums2) {
        Map<Integer, Integer> count1 = new HashMap<>();
        for (int num : nums1) {
            count1.put(num, count1.getOrDefault(num, 0) + 1);
        }

        List<Integer> result = new ArrayList<>();
        for (int num : nums2) {
            if (count1.getOrDefault(num, 0) > 0) {
                result.add(num);
                count1.put(num, count1.get(num) - 1);
            }
        }

        return result;
    }

    public static List<String> splitWords(String s) {
        return s.isEmpty() ? List.of() : Arrays.asList(s.split(" "));
    }

    public static void main(String[] args) {
        java.util.Scanner scanner = new java.util.Scanner(System.in);
        List<Integer> nums1 = splitWords(scanner.nextLine()).stream().map(Integer::parseInt).collect(Collectors.toList());
        List<Integer> nums2 = splitWords(scanner.nextLine()).stream().map(Integer::parseInt).collect(Collectors.toList());
        scanner.close();
        List<Integer> res = intersectionOfArrays(nums1, nums2);
        System.out.println(res.stream().sorted().map(String::valueOf).collect(Collectors.joining(" ")));
    }
}
